SELECT COALESCE(NULLIF(parent_asin, ''), asin) AS dedupKey, COUNT(*) AS variantCount FROM premium_products WHERE marketplace = #{marketplace} AND deleted = 0 AND title IS NOT NULL AND sellersprite_raw_json IS NOT NULL AND TRIM(sellersprite_raw_json) != '' AND COALESCE(NULLIF(parent_asin, ''), asin) IN
#{key}
GROUP BY COALESCE(NULLIF(parent_asin, ''), asin)
